insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-curriqunet-plain-pairs-scope-s668','decision','curriQunet plain/2.0 pairs: read the 8 Mathematics and Physics originals from 2025-2026','S668: of 20 plain programs at 14 curriQunet colleges that read a 2.0 page, the 8 Mathematics and Physics originals are read from their 2025-2026 archives. The 12 Business Administration and Communication Studies originals stay as filed (their 2.0s are older; Riverside City''s archive 7 already printed Business Administration 2.0), reopened per college only on an archive that prints the original.',array['program-requirements-harvest','curriqunet','decision'],'proposed','S668; the program-requirements-harvest lane NEXT (2)',null,null,'SkyPipit (S668)',date '2026-11-16'),
('d-prior-read-forces-past-no-gain-s668','decision','A prior-year read names its programs in force','S668: a prior-year read names its programs in force, since held_no_gain compares the new read with the filed record, which is another catalog year, and would hold a correct prior read. The kept-passing guard still runs. Applied to Butte 31950 and 31953 and Rio Hondo 32258.',array['program-requirements-harvest','prior-year','decision'],'proposed','S668; the program-requirements-harvest lane',null,null,'SkyPipit (S668)',date '2026-11-16'),
('d-ncl-page-yield-s668','decision','The no-closed-list lookup''s page yield (#3408)','S668, #3408 (929e1e6c): a no-list program whose only match is a page held by one closed-list program, under a heading not naming the holder, takes the page when the holder''s filed record, read from that page in the lookup''s catalog year, fails passes_live. A passing holder keeps its page. Yields persist in capture.json with their catalog_year. Census: 13 yields at 8 colleges, 0 passing moved.',array['program-requirements-harvest','slice-a','decision'],'proposed','S668; #3408 and COBIx''s three review rounds',null,null,'SkyPipit (S668)',date '2026-11-16'),
('d-no-list-record-scored-without-state-list-s668','decision','A record for a program with no state list scores as no_state_list','S668, #3414: a record for a program the state lists no courses for scores coverage and invented as no_state_list, never counts as passing, and the load holds it until the tab shows it. Extraction runs only with at least one named course. NCL_EXTRACT stays off until the display build and the Commons sidecars both hold these records back.',array['program-requirements-harvest','slice-b','decision'],'proposed','S668; #3414 and its second reader',null,null,'SkyPipit (S668)',date '2026-11-16'),
('f-curriqunet-historical-catalogs-s668','fact','curriQunet lists a host''s past catalogs','S668, free page reads 43947867258 and 43949402694: curriQunet''s Catalog/_getHistoricalCatalogs names each host''s past catalogs; Catalog/archive/<Id> settles on /iq/<cover> and asks _getNavigation?id=<Id>. The 2025-2026 ids: Berkeley City 9573, Butte 12, Gavilan 424, Rio Hondo 13, Santa Ana 19.',array['program-requirements-harvest','curriqunet','fact'],'proposed','S668; plans kb/college_reads/*_prior_catalog_list.json on claude/curriqunet-prior-pairs-s668',null,null,'SkyPipit (S668)',date '2026-11-16'),
('p-yield-holder-live-row-after-filing-s668','procedure','Remove a yield holder''s live row only after its college''s filing drops it','S668: the 13 yield holders'' live program_requirement_records rows come out with a receipt only after each college''s filing drops the record. The load is insert-only, so a row removed earlier is reinserted by the next load from the filed record. Skyline reads first under the yield code; the other 7 colleges capture again under the new code first.',array['program-requirements-harvest','slice-a','procedure'],'proposed','S668; the program-requirements-harvest lane NEXT (3)',null,null,'SkyPipit (S668)',date '2026-11-16'),
('d-gavilan-originals-filed-s668','decision','Gavilan Mathematics 31444 and Physics 33047 filed from 2025-2026 (#3411)','S668, #3411 (2bcb6dea): Gavilan Mathematics 31444 and Physics 33047 read from their own 2025-2026 catalog (curriQunet archive 424): 5 of 5 and 6 of 6 placed, none invented, arithmetic equal, $0.10. Reread run 43962460208 replaced 2 rows, held 0 (receipt kb/receipts/program_requirement_records_college_reread_gavilan_43962460208.json); the Commons outcomes sidecar was regenerated.',array['program-requirements-harvest','gavilan','decision'],'proposed','S668; #3411',null,null,'SkyPipit (S668)',date '2026-11-16'),
('p-execute-sql-prompt-is-the-apps-s668','procedure','The Execute SQL card is the app''s per-call prompt','Sam, in session S668, 20:10Z 2026-11-16, of the Execute SQL card: "I okd this but you have auth to do this without asking..." The card is the app''s per-call prompt (approval_prompt_hooks), which no repo setting clears, so sessions keep live reads few and batched into one call, and writes go through the runner.',array['governance-team-enablement','supabase','procedure','sam'],'verified','Sam in session S668, 20:10Z 2026-11-16; docs/reference/approval_prompt_hooks.md','Sam Lee',now(),'SkyPipit (S668)',date '2026-11-16')
on conflict (slug) do nothing;

